	HeadShare: 0.25,      // share of the hits that land on the head
	QtePower: 0.75,       // typical QTE result, 0 = Min, 0.5 = Base, 1 = Max
	AvoidedDamage: 0.65,  // share of the incoming damage a competent player avoids
	SkillPointBudget: 36, // points the player should own before the final boss
