// One-off: apply the first batch of balance numbers to keys that already exist in the data files.
'use strict';
const fs = require('fs');
const path = require('path');
const dir = path.join('C:/GameJam/Glyphbound/Content/Data');
const read = (n) => fs.readFileSync(path.join(dir, n), 'utf8');
function setIn(text, anchor, key, value) {
	// Replaces the first `"key": <number>` found after `anchor` (literal search, keeps the file's formatting).
	const at = text.indexOf(anchor);
	if (at < 0) { throw new Error('anchor not found: ' + anchor); }
	const re = new RegExp('("' + key.replace(/\./g, '\\.') + '":\\s*)-?[0-9.]+');
	const tail = text.slice(at);
	if (!re.test(tail)) { throw new Error('key not found after ' + anchor + ': ' + key); }
	return text.slice(0, at) + tail.replace(re, (m, p1) => p1 + value);
}
function setParam(text, spellId, param, base, min, max) {
	const at = text.indexOf('"Id": "' + spellId + '"');
	if (at < 0) { throw new Error('spell not found: ' + spellId); }
	const pAt = text.indexOf('"' + param + '": {', at);
	if (pAt < 0) { throw new Error('param not found: ' + spellId + '.' + param); }
	let out = text;
	out = setIn(out.slice(0, pAt) + out.slice(pAt), '', '', 0).slice(0, 0) || out; // no-op guard
	const head = out.slice(0, pAt);
	let tail = out.slice(pAt);
	tail = tail.replace(/("Base":\s*)-?[0-9.]+/, (m, p) => p + base);
	tail = tail.replace(/("Min":\s*)-?[0-9.]+/, (m, p) => p + min);
	tail = tail.replace(/("Max":\s*)-?[0-9.]+/, (m, p) => p + max);
	return head + tail;
}

// Player
let t = read('Player.json');
t = setIn(t, '"Stats"', 'HealthRegen', 3);
t = setIn(t, '"Stats"', 'HealthRegenDelay', 6);
fs.writeFileSync(path.join(dir, 'Player.json'), t);

// Weapons
t = read('Weapons.json');
t = setIn(t, '"Id": "Staff_Ember"', 'FireBuildUp', 18);
t = setIn(t, '"Id": "Pistol"', 'Damage', 20);
t = setIn(t, '"Id": "Pistol"', 'FireInterval', 0.25);
t = setIn(t, '"Id": "Pistol"', 'MagazineSize', 15);
t = setIn(t, '"Id": "Pistol"', 'SpareMagazines', 6);
t = setIn(t, '"Id": "Shotgun"', 'FireInterval', 0.8);
for (const e of ['FireBuildUp', 'LightningBuildUp', 'IceBuildUp']) { t = setIn(t, '"Id": "Shotgun"', e, 40); }
t = setIn(t, '"Id": "Rifle"', 'Damage', 12);
t = setIn(t, '"Id": "Rifle"', 'SpareMagazines', 5);
for (const e of ['FireBuildUp', 'LightningBuildUp', 'IceBuildUp']) { t = setIn(t, '"Id": "Rifle"', e, 6); }
t = setIn(t, '"Id": "ElementalSword"', 'Damage', 50);
for (const e of ['FireBuildUp', 'LightningBuildUp', 'IceBuildUp']) { t = setIn(t, '"Id": "ElementalSword"', e, 25); }
fs.writeFileSync(path.join(dir, 'Weapons.json'), t);

// Spells
t = read('Spells.json');
t = setParam(t, 'Fireball', 'Cooldown', 1.5, 1.5, 1.5);
t = setParam(t, 'FireWall', 'Cooldown', 10, 10, 10);
t = setParam(t, 'FireWall', 'DamagePerSecond', 30, 15, 45);
t = setParam(t, 'FireWall', 'BuildUp', 20, 20, 20);
t = setParam(t, 'Flamethrower', 'DamagePerSecond', 50, 30, 70);
t = setParam(t, 'LightningBolt', 'Cooldown', 0.8, 0.8, 0.8);
t = setParam(t, 'LightningRune', 'Cooldown', 6, 6, 6);
t = setParam(t, 'LightningRune', 'Damage', 80, 45, 115);
t = setParam(t, 'StaticOrb', 'DamagePerSecond', 35, 20, 50);
t = setParam(t, 'StaticOrb', 'BuildUp', 12, 12, 12);
t = setParam(t, 'StaticOrb', 'Speed', 300, 300, 300);
t = setParam(t, 'IceWall', 'Cooldown', 12, 12, 12);
t = setParam(t, 'IceShield', 'ManaCost', 20, 20, 20);
t = setParam(t, 'IceShield', 'Cooldown', 18, 18, 18);
t = setParam(t, 'IceShield', 'Duration', 12, 8, 16);
t = setParam(t, 'IceShield', 'Health', 80, 40, 120);
t = setParam(t, 'IceFloor', 'Cooldown', 10, 10, 10);
t = setParam(t, 'WeaponEnchant', 'Cooldown', 18, 18, 18);
fs.writeFileSync(path.join(dir, 'Spells.json'), t);
console.log('ok');
EOF
