// One-off: first batch of balance numbers on keys that already exist (Player, Weapons, Spells).
'use strict';
const fs = require('fs');
const path = require('path');
const dir = 'C:/GameJam/Glyphbound/Content/Data';
function edit(name, fn) {
	const file = path.join(dir, name);
	const raw = fs.readFileSync(file, 'utf8');
	const crlf = raw.indexOf('\r\n') >= 0;
	const bom = raw.charCodeAt(0) === 0xFEFF;
	const obj = JSON.parse(bom ? raw.slice(1) : raw);
	fn(obj);
	let out = JSON.stringify(obj, null, '\t') + '\n';
	if (crlf) { out = out.split('\n').join('\r\n'); }
	fs.writeFileSync(file, (bom ? '\uFEFF' : '') + out);
}
const must = (o, k) => { if (!(k in o)) { throw new Error('missing key ' + k); } };
const set = (o, k, v) => { must(o, k); o[k] = v; };

edit('Player.json', (p) => { set(p.Stats, 'HealthRegen', 3); set(p.Stats, 'HealthRegenDelay', 6); });

edit('Weapons.json', (w) => {
	const by = (id) => { const x = w.Weapons.find((y) => y.Id === id); if (!x) { throw new Error(id); } return x.Stats; };
	const bu = (s, v) => { for (const e of ['FireBuildUp', 'LightningBuildUp', 'IceBuildUp']) { set(s, e, v); } };
	set(by('Staff_Ember'), 'FireBuildUp', 18);
	set(by('Pistol'), 'Damage', 20); set(by('Pistol'), 'FireInterval', 0.25); set(by('Pistol'), 'MagazineSize', 15); set(by('Pistol'), 'SpareMagazines', 6);
	set(by('Shotgun'), 'FireInterval', 0.8); bu(by('Shotgun'), 40);
	set(by('Rifle'), 'Damage', 12); set(by('Rifle'), 'SpareMagazines', 5); bu(by('Rifle'), 6);
	set(by('ElementalSword'), 'Damage', 50); bu(by('ElementalSword'), 25);
});

edit('Spells.json', (s) => {
	const P = (id, param, base, min, max) => {
		const sp = s.Spells.find((y) => y.Id === id); if (!sp) { throw new Error(id); }
		must(sp.Params, param);
		sp.Params[param].Base = base; sp.Params[param].Min = min === undefined ? base : min; sp.Params[param].Max = max === undefined ? base : max;
	};
	P('Fireball', 'Cooldown', 1.5);
	P('FireWall', 'Cooldown', 10); P('FireWall', 'DamagePerSecond', 30, 15, 45); P('FireWall', 'BuildUp', 20);
	P('Flamethrower', 'DamagePerSecond', 50, 30, 70);
	P('LightningBolt', 'Cooldown', 0.8);
	P('LightningRune', 'Cooldown', 6); P('LightningRune', 'Damage', 80, 45, 115);
	P('StaticOrb', 'DamagePerSecond', 35, 20, 50); P('StaticOrb', 'BuildUp', 12); P('StaticOrb', 'Speed', 300);
	P('IceWall', 'Cooldown', 12);
	P('IceShield', 'ManaCost', 20); P('IceShield', 'Cooldown', 18); P('IceShield', 'Duration', 12, 8, 16); P('IceShield', 'Health', 80, 40, 120);
	P('IceFloor', 'Cooldown', 10);
	P('WeaponEnchant', 'Cooldown', 18);
});
console.log('ok');
EOF
