// One-off: a fourth sub-wave for the regular waves and the elemental zones (fights were coming out at 40-50 s, target 60-90 s),
// and a fight-length estimate in the model. Encounters.json is rewritten in its own compact style.
'use strict';
const fs = require('fs');
const f = 'C:/GameJam/Glyphbound/Content/Data/Encounters.json';
const data = JSON.parse(fs.readFileSync(f, 'utf8'));
const add = {
	Wave_Past_1: [['Orc_Past', 4], ['Orc_Past_Shaman', 2], ['Orc_Past_Champion', 1]],
	Wave_Past_2: [['Orc_Past_Champion', 2], ['Orc_Past', 3], ['Imp_Past', 4]],
	Wave_Past_3: [['Orc_Past_Juggernaut', 1], ['Orc_Past_Champion', 2], ['Imp_Past', 5]],
	Wave_Future_1: [['Orc_Future', 4], ['Orc_Future_Enforcer', 1], ['Drone_Future', 3]],
	Wave_Future_2: [['Orc_Future_Enforcer', 2], ['Orc_Future', 3], ['Drone_Future', 4]],
	Wave_Future_3: [['Orc_Future_Siege', 1], ['Orc_Future_Enforcer', 2], ['Drone_Future', 5]],
	Zone_Fire: [['Orc_Past_Juggernaut', 1], ['Orc_Past', 4], ['Orc_Past_Shaman', 2]],
	Zone_Lightning: [['Orc_Past_Champion', 2], ['Imp_Past', 6], ['Orc_Past_Shaman', 2]],
	Zone_Ice: [['Orc_Past_Juggernaut', 1], ['Imp_Past', 6], ['Orc_Past', 3]],
	Zone_Air: [['Orc_Past_Juggernaut', 1], ['Orc_Past_Champion', 1], ['Orc_Past_Shaman', 3], ['Imp_Past', 4]]
};
for (const id of Object.keys(add)) {
	const enc = data.Encounters.find((e) => e.Id === id);
	if (!enc) { throw new Error(id); }
	if (enc.Waves.length !== 3) { throw new Error(id + ' already has ' + enc.Waves.length + ' waves'); }
	enc.Waves.push({ DelayBefore: 2.0, Spawns: add[id].map(([EnemyId, Count]) => ({ EnemyId, Count })) });
}
const n = (v) => Number.isInteger(v) && String(v).indexOf('.') < 0 ? String(v) : String(v);
const drop = (d) => '{ "ItemId": "' + d.ItemId + '", "Count": ' + d.Count + ', "Chance": ' + (Number.isInteger(d.Chance) ? d.Chance.toFixed(1) : d.Chance) + ' }';
let out = '{\n\t"Encounters": [\n';
out += data.Encounters.map((e) => {
	let s = '\t\t{\n\t\t\t"Id": "' + e.Id + '",\n\t\t\t"Waves": [\n';
	s += e.Waves.map((w) => '\t\t\t\t{\n\t\t\t\t\t"DelayBefore": ' + (w.DelayBefore === 0 ? '0' : w.DelayBefore.toFixed(1)) + ',\n\t\t\t\t\t"Spawns": [\n' +
		w.Spawns.map((sp) => '\t\t\t\t\t\t{ "EnemyId": "' + sp.EnemyId + '", "Count": ' + sp.Count + ' }').join(',\n') + '\n\t\t\t\t\t]\n\t\t\t\t}').join(',\n');
	s += '\n\t\t\t],\n\t\t\t"SkillPoints": ' + e.SkillPoints + ',\n\t\t\t"Rewards": [' + (e.Rewards.length ? '\n' + e.Rewards.map((d) => '\t\t\t\t' + drop(d)).join(',\n') + '\n\t\t\t' : '') + ']\n\t\t}';
	return s;
}).join(',\n');
out += '\n\t]\n}\n';
JSON.parse(out);
fs.writeFileSync(f, out);

// Model: fight length estimate.
const m = 'C:/GameJam/Tools/Balance/balance_model.js';
let t = fs.readFileSync(m, 'utf8');
function rep(a, b) { if (t.split(a).length !== 2) { throw new Error('anchor: ' + a.slice(0, 50)); } t = t.split(a).join(b); }
rep(`	SkillPointBudget: 36, // points the player should own before the final boss
`, `	SkillPointBudget: 36, // points the player should own before the final boss
	WaveOverhead: 6,      // seconds lost per sub-wave: spawn delay, enemies walking in, finding targets
	BuildMult: 1.3,       // gun damage of a mid-game build over the base gun (perks, enchant)
`);
rep(`W = [18, 4, 7, 8, 44];
line(['Encounter', 'SP', 'Kills', 'Health', 'Per wave: kills, health, raw dmg/s -> expected dmg/s (seconds to die)'], W);`,
`W = [18, 4, 7, 8, 9, 44];
const fightDps = bestGun * ASSUME.BuildMult + spellDps;
line(['Encounter', 'SP', 'Kills', 'Health', 'Seconds', 'Per wave: kills, health, raw dmg/s -> expected dmg/s (seconds to die)'], W);`);
rep(`	line([enc.Id, enc.SkillPoints, kills, health, parts.join(' | ')], W);`, `	line([enc.Id, enc.SkillPoints, kills, health, num(health / fightDps + enc.Waves.length * ASSUME.WaveOverhead, 0), parts.join(' | ')], W);`);
rep(`	line([enc.Id, enc.SkillPoints, kills, health, num(health / fightDps + enc.Waves.length * ASSUME.WaveOverhead, 0), parts.join(' | ')], W);
}`, `	line([enc.Id, enc.SkillPoints, kills, health, num(health / fightDps + enc.Waves.length * ASSUME.WaveOverhead, 0), parts.join(' | ')], W);
}
console.log('Seconds = health / ' + num(fightDps, 0) + ' expected dmg/s (mid-game build) + ' + ASSUME.WaveOverhead + ' s per sub-wave. Targets: waves 60-90, sub-bosses 40-60, Valkyries about 120, Entity about 180.');`);
fs.writeFileSync(m, t);
console.log('ok');
EOF
