		const get = (k) => e.Stats[el + k] === undefined ? game['ElementalDefault.' + el + k] : e.Stats[el + k];
		return el + ' ' + get('BuildUpThreshold') + ' x' + get('BuildUpTaken') + ' x' + get('DamageTaken');
