'use strict';
const fs = require('fs');
const dir = 'C:/GameJam/Glyphbound/Content/Data/';

// ---- Enemies.json (text edits inside one enemy block, keeps formatting) ----
let t = fs.readFileSync(dir + 'Enemies.json', 'utf8');
function block(id) {
	const at = t.indexOf('"Id": "' + id + '"');
	if (at < 0) { throw new Error('enemy ' + id); }
	let end = t.indexOf('"Id": "', at + 10);
	if (end < 0) { end = t.length; }
	return [at, end];
}
function inEnemy(id, from, to) {
	const [at, end] = block(id);
	const pos = t.indexOf(from, at);
	if (pos < 0 || pos > end) { throw new Error(id + ': ' + from); }
	t = t.slice(0, pos) + to + t.slice(pos + from.length);
}
inEnemy('Orc_Past_Brute', '"MaxHealth": 2400,', '"MaxHealth": 2700,');
inEnemy('Valkyrie_Past', '"MaxHealth": 9000,', '"MaxHealth": 7200,');
inEnemy('Valkyrie_Future', '"MaxHealth": 10000,', '"MaxHealth": 7600,');
// Resistance to the ice floor slow (new stat read by the status effect component).
for (const id of ['Orc_Past_Juggernaut', 'Orc_Past_Brute', 'Orc_Future_Siege', 'Orc_Future_Warlord']) { inEnemy(id, '"FrostSlow": 0.4,', '"FrostSlow": 0.4,\n\t\t\t\t"SlowTaken": 0.6,'); }
for (const id of ['Valkyrie_Past', 'Valkyrie_Future', 'Entity_Phase1', 'Entity_Phase2']) { inEnemy(id, '"FrostSlow": 0.25,', '"FrostSlow": 0.25,\n\t\t\t\t"SlowTaken": 0.4,'); }
// Ammo drops: a mid-game build must not get more rounds back than it spends.
const ammo = (c) => '{ "ItemId": "Ammo_Magazine", "Count": 1, "Chance": ' + c + ' }';
inEnemy('Imp_Past', ammo('0.04'), ammo('0.03'));
inEnemy('Orc_Past', ammo('0.1'), ammo('0.06'));
inEnemy('Orc_Past_Shaman', ammo('0.1'), ammo('0.06'));
inEnemy('Orc_Past_Champion', ammo('0.25'), ammo('0.15'));
inEnemy('Orc_Past_Juggernaut', ammo('0.5'), ammo('0.35'));
inEnemy('Drone_Future', ammo('0.08'), ammo('0.06'));
inEnemy('Orc_Future', ammo('0.2'), ammo('0.12'));
inEnemy('Orc_Future_Enforcer', ammo('0.45'), ammo('0.3'));
inEnemy('Orc_Future_Siege', ammo('1.0') + ',\n\t\t\t\t' + ammo('0.3'), ammo('0.7'));
JSON.parse(t);
fs.writeFileSync(dir + 'Enemies.json', t);

