const crlf = raw.indexOf('\r\n') >= 0;
const s = JSON.parse(raw);
const P = (id, param, base, min, max) => {
	const sp = s.Spells.find((y) => y.Id === id);
	if (!sp || !sp.Params[param]) { throw new Error(id + '.' + param); }
	sp.Params[param].Base = base; sp.Params[param].Min = min === undefined ? base : min; sp.Params[param].Max = max === undefined ? base : max;
};
P('IceWall', 'Cooldown', 16);
P('IceShield', 'Cooldown', 24);
P('IceFloor', 'Cooldown', 12);
P('IceFloor', 'EffectDuration', 0.25);   // x Slow.Duration (4 s): the slow lingers 1 s after leaving the floor, not 4
P('StaticOrb', 'Range', 2700, 1800, 3600); // so Persistent Charge is never cut short by the range
let out = JSON.stringify(s, null, '\t') + '\n';
if (crlf) { out = out.split('\n').join('\r\n'); }
fs.writeFileSync(dir + 'Spells.json', out);

// ---- Encounters.json: a fifth sub-wave (the last one again) for waves and zones ----
let e = fs.readFileSync(dir + 'Encounters.json', 'utf8');
