for (const enc of data.Encounters) {
	if (enc.Id.indexOf('Wave_') !== 0 && enc.Id.indexOf('Zone_') !== 0) { continue; }
	if (enc.Waves.length !== 4) { throw new Error(enc.Id + ' has ' + enc.Waves.length); }
	enc.Waves.push(JSON.parse(JSON.stringify(enc.Waves[3])));
}
const drop = (d) => '{ "ItemId": "' + d.ItemId + '", "Count": ' + d.Count + ', "Chance": ' + (Number.isInteger(d.Chance) ? d.Chance.toFixed(1) : d.Chance) + ' }';
let o = '{\n\t"Encounters": [\n';
o += data.Encounters.map((x) => {
	let r = '\t\t{\n\t\t\t"Id": "' + x.Id + '",\n\t\t\t"Waves": [\n';
	r += x.Waves.map((w) => '\t\t\t\t{\n\t\t\t\t\t"DelayBefore": ' + (w.DelayBefore === 0 ? '0' : w.DelayBefore.toFixed(1)) + ',\n\t\t\t\t\t"Spawns": [\n' +
		w.Spawns.map((sp) => '\t\t\t\t\t\t{ "EnemyId": "' + sp.EnemyId + '", "Count": ' + sp.Count + ' }').join(',\n') + '\n\t\t\t\t\t]\n\t\t\t\t}').join(',\n');
	r += '\n\t\t\t],\n\t\t\t"SkillPoints": ' + x.SkillPoints + ',\n\t\t\t"Rewards": [' + (x.Rewards.length ? '\n' + x.Rewards.map((d) => '\t\t\t\t' + drop(d)).join(',\n') + '\n\t\t\t' : '') + ']\n\t\t}';
	return r;
}).join(',\n');
o += '\n\t]\n}\n';
JSON.parse(o);
fs.writeFileSync(dir + 'Encounters.json', o);
console.log('ok');
EOF
